'use client'

import { useEffect } from 'react'

/**
 * App Router error boundary.
 *
 * Replaces the Pages Router `pages/_error.js` file. The former
 * `Error.getInitialProps` pattern (which derived a `statusCode` from `res`/`err`)
 * does not exist in the App Router; instead this component receives the thrown
 * `error` and a `reset()` callback to attempt recovery.
 */
export default function Error({
  error,
  reset,
}: {
  error: Error & { digest?: string }
  reset: () => void
}) {
  useEffect(() => {
    // eslint-disable-next-line no-console
    console.error(error)
  }, [error])

  return (
    <div className="error-page">
      <h1>Something went wrong!</h1>
      <p>Sorry, something went wrong.</p>
      <button onClick={() => reset()}>Try again</button>
    </div>
  )
}

