import { NextRequest, NextResponse } from 'next/server'
import type { ApiPost } from '@/types'

type Params = { id: string }

// Route Handlers automatically return 405 for unsupported methods, so the
// former `res.setHeader('Allow', ...)` / `res.status(405).end(...)` handling
// from the Pages Router API route is no longer needed.

export async function GET(
  _request: NextRequest,
  { params }: { params: Promise<Params> }
): Promise<NextResponse<ApiPost>> {
  const { id } = await params

  const post: ApiPost = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post)
}

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<Params> }
): Promise<NextResponse<ApiPost>> {
  const { id } = await params

  const body = (await request.json()) as { title?: string; content?: string }
  const { title, content } = body

  const updatedPost: ApiPost = {
    id: parseInt(id, 10),
    title: title ?? `Post ${id}`,
    content: content ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost)
}

export async function DELETE(
  _request: NextRequest,
  { params }: { params: Promise<Params> }
): Promise<NextResponse<{ message: string }>> {
  const { id } = await params

  return NextResponse.json({ message: `Post ${id} deleted successfully` })
}

