'use client'

import { createContext, useContext, useState, type ReactNode } from 'react'

type Theme = 'light' | 'dark'

type AppContextValue = {
  theme: Theme
  setTheme: (theme: Theme) => void
}

const AppContext = createContext<AppContextValue | undefined>(undefined)

export function AppProvider({ children }: { children: ReactNode }) {
  const [theme, setTheme] = useState<Theme>('light')

  return (
    <AppContext.Provider value={{ theme, setTheme }}>
      {children}
    </AppContext.Provider>
  )
}

export function useAppContext(): AppContextValue {
  const context = useContext(AppContext)
  if (!context) {
    throw new Error('useAppContext must be used within AppProvider')
  }
  return context
}

'use client'

import { useRouter } from 'next/navigation'
import type { ReactNode } from 'react'

type NavButtonProps = {
  /** Destination to push to. Ignored when `back` is set. */
  href?: string
  /** Navigate back in history instead of pushing to `href`. */
  back?: boolean
  children: ReactNode
}

/**
 * Client-side navigation button.
 *
 * Replaces the Pages Router `useRouter` (from `next/router`) usage with the
 * App Router `useRouter` from `next/navigation`.
 */
export function NavButton({ href, back = false, children }: NavButtonProps) {
  const router = useRouter()

  return (
    <button
      onClick={() => {
        if (back) {
          router.back()
        } else if (href) {
          router.push(href)
        }
      }}
    >
      {children}
    </button>
  )
}

