import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { NavButton } from '@/components/NavButton'
import type { Comment, Post } from '@/types'

// Equivalent to the former `getStaticProps` with `revalidate: 300` (ISR).
export const revalidate = 300

type Params = { id: string }

/**
 * Equivalent to the former `getStaticPaths`. The default App Router behavior
 * (`dynamicParams = true`) matches the Pages Router `fallback: 'blocking'`
 * setting: paths not listed here are rendered on-demand and then cached.
 */
export async function generateStaticParams(): Promise<Params[]> {
  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

async function getPost(id: string): Promise<Post | null> {
  const post: Post = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}`
  ).then((res) => res.json())
  return post?.id ? post : null
}

export async function generateMetadata({
  params,
}: {
  params: Promise<Params>
}): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id)
  if (!post) {
    return {}
  }

  const description = post.body.substring(0, 160)

  return {
    title: post.title,
    description,
    // The `title` template adds "- My Blog", but the original og:title was
    // just the post title, so set it explicitly.
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPostPage({
  params,
}: {
  params: Promise<Params>
}): Promise<React.JSX.Element> {
  const { id } = await params

  let post: Post | null = null
  let comments: Comment[] = []

  try {
    const [postResult, commentsResult] = await Promise.all([
      getPost(id),
      fetch(
        `https://jsonplaceholder.typicode.com/posts/${id}/comments`
      ).then((res) => res.json() as Promise<Comment[]>),
    ])
    post = postResult
    comments = commentsResult
  } catch {
    notFound()
  }

  if (!post) {
    notFound()
  }

  return (
    <article>
      <NavButton back>← Back</NavButton>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

