import { NextRequest, NextResponse } from 'next/server'
import type { ApiPost } from '@/types'

// Route Handlers automatically return 405 for unsupported methods, so the
// former `res.setHeader('Allow', ...)` / `res.status(405).end(...)` handling
// from the Pages Router API route is no longer needed.

export async function GET(): Promise<NextResponse<ApiPost[]>> {
  const posts: ApiPost[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return NextResponse.json(posts)
}

export async function POST(
  request: NextRequest
): Promise<NextResponse<ApiPost | { error: string }>> {
  const body = (await request.json()) as { title?: string; content?: string }
  const { title, content } = body

  if (!title || !content) {
    return NextResponse.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  const newPost: ApiPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(newPost, { status: 201 })
}

import { NextRequest, NextResponse } from 'next/server'
